-- Macrova: full schema (Phase 2).
-- Conventions:
--  * ids are UUIDs generated by the client (offline-safe, idempotent upserts)
--  * every personal table has user_id -> auth.users ON DELETE CASCADE, created_at, updated_at
--  * synced tables use deleted_at (soft delete) so deletions propagate to other devices
--  * log_date is a plain DATE in the user's local calendar (no timezone drift)
--  * quantities stored metric (g, ml, m, s, kg)
--  * RLS on every table; API access is granted explicitly (project has no auto-grants)

-- ---------------------------------------------------------------- enums
create type public.data_source as enum ('off', 'usda', 'bedca', 'ciqual', 'user', 'manual_estimate');
create type public.sex_type as enum ('male', 'female');
create type public.goal_type as enum ('maintain', 'lose_fat', 'gain_muscle', 'recomp', 'custom');
create type public.exercise_mode as enum ('fixed', 'dynamic');

-- ---------------------------------------------------------------- user config
create table public.physical_profiles (
  user_id uuid primary key references auth.users (id) on delete cascade,
  birth_date date,
  sex public.sex_type,            -- used only for the selected metabolic equation
  height_cm numeric(5,1) check (height_cm is null or height_cm between 50 and 260),
  weight_kg numeric(5,2) check (weight_kg is null or weight_kg between 20 and 500),
  activity_level text check (activity_level in ('sedentary','light','moderate','active','very_active','custom')),
  goal public.goal_type not null default 'maintain',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.nutrition_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  bmr_override numeric(7,1) check (bmr_override is null or bmr_override > 0),
  tdee_override numeric(7,1) check (tdee_override is null or tdee_override > 0),
  activity_multiplier numeric(4,3) check (activity_multiplier is null or activity_multiplier between 1 and 3),
  calorie_delta numeric(7,1) not null default 0,         -- negative = deficit, positive = surplus
  calorie_target_override numeric(7,1) check (calorie_target_override is null or calorie_target_override > 0),
  exercise_mode public.exercise_mode not null default 'fixed',
  activity_includes_exercise boolean not null default true, -- avoids double counting habitual exercise
  weekly_mode text not null default 'same' check (weekly_mode in ('same', 'per_day')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Targets are versioned by effective date so history keeps the goals that were active then.
create table public.nutrition_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  weekday smallint check (weekday between 0 and 6),       -- 0 = Monday; NULL = every day
  kcal numeric(7,1) not null check (kcal >= 0),
  protein_g numeric(6,1) not null check (protein_g >= 0),
  carbs_g numeric(6,1) not null check (carbs_g >= 0),
  fat_g numeric(6,1) not null check (fat_g >= 0),
  effective_from date not null,
  effective_to date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check (effective_to is null or effective_to >= effective_from)
);
create index nutrition_targets_user_idx on public.nutrition_targets (user_id, effective_from desc);

-- ---------------------------------------------------------------- foods
-- Global catalog rows have owner_id NULL (written only by service_role / Edge Functions).
-- Rows with owner_id = a user are that user's custom foods.
create table public.foods (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users (id) on delete cascade,
  source public.data_source not null,
  source_ref text,                 -- id in the external database (e.g. barcode / fdcId)
  barcode text,
  name text not null,
  brand text,
  category text,
  image_url text,
  basis text not null default 'g' check (basis in ('g', 'ml')),
  kcal_100 numeric(8,2) not null check (kcal_100 >= 0),
  protein_100 numeric(7,2) not null check (protein_100 >= 0),
  carbs_100 numeric(7,2) not null check (carbs_100 >= 0),
  fat_100 numeric(7,2) not null check (fat_100 >= 0),
  fiber_100 numeric(7,2) check (fiber_100 is null or fiber_100 >= 0),
  sugar_100 numeric(7,2) check (sugar_100 is null or sugar_100 >= 0),
  salt_100 numeric(7,3) check (salt_100 is null or salt_100 >= 0),
  serving_size numeric(8,2) check (serving_size is null or serving_size > 0),
  serving_label text,
  verified boolean not null default false,   -- true only for reviewed external data, never user input
  attribution text,
  fetched_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check ((owner_id is null) = (source <> 'user' and source <> 'manual_estimate')),
  check (owner_id is not null or source_ref is not null)
);
create unique index foods_global_source_uidx on public.foods (source, source_ref) where owner_id is null;
create index foods_barcode_idx on public.foods (barcode) where barcode is not null;
create index foods_owner_idx on public.foods (owner_id) where owner_id is not null;
create extension if not exists pg_trgm with schema extensions;
create index foods_name_trgm_idx on public.foods using gin (name extensions.gin_trgm_ops);

create table public.food_favorites (
  user_id uuid not null references auth.users (id) on delete cascade,
  food_id uuid not null references public.foods (id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, food_id)
);

create table public.meal_types (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  default_key text check (default_key in ('breakfast','mid_morning','lunch','snack','dinner','other_snacks')),
  name text,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check (default_key is not null or (name is not null and length(btrim(name)) > 0))
);
create index meal_types_user_idx on public.meal_types (user_id, sort_order);

-- Each entry stores a SNAPSHOT of the nutrition at consumption time, so later catalog
-- changes never alter history.
create table public.food_log_entries (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  log_date date not null,
  meal_type_id uuid references public.meal_types (id) on delete set null,
  food_id uuid references public.foods (id) on delete set null,
  name text not null,
  brand text,
  quantity numeric(9,2) not null check (quantity > 0),
  unit text not null default 'g' check (unit in ('g', 'ml', 'serving')),
  quantity_base numeric(9,2) not null check (quantity_base > 0), -- grams or ml actually eaten
  kcal numeric(9,2) not null check (kcal >= 0),
  protein_g numeric(8,2) not null check (protein_g >= 0),
  carbs_g numeric(8,2) not null check (carbs_g >= 0),
  fat_g numeric(8,2) not null check (fat_g >= 0),
  fiber_g numeric(8,2),
  per_100 jsonb not null,                 -- nutrient values per 100 g/ml used for the calculation
  source public.data_source not null,
  source_ref text,
  verified boolean not null default false,
  fetched_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index food_log_user_date_idx on public.food_log_entries (user_id, log_date) where deleted_at is null;
create index food_log_updated_idx on public.food_log_entries (user_id, updated_at);

create table public.saved_meals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (length(btrim(name)) > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create table public.saved_meal_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  saved_meal_id uuid not null references public.saved_meals (id) on delete cascade,
  food_id uuid references public.foods (id) on delete set null,
  name text not null,
  brand text,
  quantity numeric(9,2) not null check (quantity > 0),
  unit text not null default 'g' check (unit in ('g', 'ml', 'serving')),
  quantity_base numeric(9,2) not null check (quantity_base > 0),
  per_100 jsonb not null,
  source public.data_source not null,
  source_ref text,
  position int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index saved_meal_items_meal_idx on public.saved_meal_items (saved_meal_id);

-- ---------------------------------------------------------------- activity
-- Extensible catalog: `fields` lists which input fields the UI shows for that sport.
create table public.activity_types (
  key text primary key,
  category text not null,
  met numeric(4,1) not null check (met > 0),   -- default MET (Compendium of Physical Activities)
  fields text[] not null default '{}',
  sort_order int not null default 0
);

create table public.activities (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  activity_type_key text not null references public.activity_types (key),
  custom_name text,
  log_date date not null,
  started_at timestamptz,
  duration_s int not null check (duration_s > 0),
  distance_m numeric(10,1) check (distance_m is null or distance_m >= 0),
  elevation_gain_m numeric(8,1) check (elevation_gain_m is null or elevation_gain_m >= 0),
  avg_hr smallint check (avg_hr is null or avg_hr between 20 and 260),
  steps int check (steps is null or steps >= 0),
  pool_length_m numeric(5,1),
  laps int,
  workout_type text,
  kcal numeric(8,1) check (kcal is null or kcal >= 0),
  kcal_source text not null default 'estimated' check (kcal_source in ('estimated', 'manual', 'strava')),
  source text not null default 'manual' check (source in ('manual', 'strava')),
  strava_activity_id bigint,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create unique index activities_strava_uidx on public.activities (user_id, strava_activity_id) where strava_activity_id is not null;
create index activities_user_date_idx on public.activities (user_id, log_date) where deleted_at is null;

-- Strava tokens: RLS on, NO policies and NO grants -> unreachable from the client.
-- Only Edge Functions (service_role) can read/write. Client reads status via get_strava_status().
create table public.strava_connections (
  user_id uuid primary key references auth.users (id) on delete cascade,
  athlete_id bigint not null,
  access_token text not null,
  refresh_token text not null,
  expires_at timestamptz not null,
  scope text,
  last_sync_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------- gym
create table public.exercises (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users (id) on delete cascade,   -- NULL = global catalog
  name text not null,
  category text not null,
  primary_muscle text not null,
  secondary_muscles text[] not null default '{}',
  equipment text,
  difficulty text check (difficulty in ('beginner', 'intermediate', 'advanced')),
  instructions text[] not null default '{}',
  variations text[] not null default '{}',
  image_url text,
  license text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index exercises_owner_idx on public.exercises (owner_id);

create table public.routines (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (length(btrim(name)) > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create table public.routine_exercises (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  routine_id uuid not null references public.routines (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete cascade,
  position int not null default 0,
  target_sets smallint check (target_sets is null or target_sets > 0),
  target_reps smallint check (target_reps is null or target_reps > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index routine_exercises_routine_idx on public.routine_exercises (routine_id, position);

create table public.workout_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  routine_id uuid references public.routines (id) on delete set null,
  name text,
  log_date date not null,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index workout_sessions_user_date_idx on public.workout_sessions (user_id, log_date);

create table public.workout_sets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  session_id uuid not null references public.workout_sessions (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete cascade,
  set_index smallint not null check (set_index >= 0),
  weight_kg numeric(6,2) check (weight_kg is null or weight_kg >= 0),
  reps smallint check (reps is null or reps >= 0),
  rest_s int check (rest_s is null or rest_s >= 0),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index workout_sets_exercise_idx on public.workout_sets (user_id, exercise_id, created_at);
create index workout_sets_session_idx on public.workout_sets (session_id);

-- ---------------------------------------------------------------- summaries / future
create table public.daily_summaries (
  user_id uuid not null references auth.users (id) on delete cascade,
  log_date date not null,
  target_snapshot jsonb not null,     -- goals active on that day (history is preserved)
  kcal_consumed numeric(9,2) not null default 0,
  protein_g numeric(8,2) not null default 0,
  carbs_g numeric(8,2) not null default 0,
  fat_g numeric(8,2) not null default 0,
  kcal_burned numeric(8,1) not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, log_date)
);

-- Not exposed in the v1 UI; present so body weight tracking can be added later without a rebuild.
create table public.body_measurements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('weight_kg', 'body_fat_pct', 'waist_cm')),
  value numeric(7,2) not null,
  measured_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index body_measurements_user_idx on public.body_measurements (user_id, kind, measured_at);

-- ---------------------------------------------------------------- triggers + RLS (owner tables)
do $$
declare t text;
begin
  foreach t in array array[
    'physical_profiles','nutrition_settings','nutrition_targets','food_favorites','meal_types',
    'food_log_entries','saved_meals','saved_meal_items','activities','routines','routine_exercises',
    'workout_sessions','workout_sets','daily_summaries','body_measurements'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', t || '_sel', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', t || '_ins', t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t || '_upd', t);
    execute format('create policy %I on public.%I for delete to authenticated using (user_id = (select auth.uid()))', t || '_del', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()', t || '_updated_at', t);
  end loop;
end $$;

-- Catalogs with global (owner_id NULL) + per-user rows.
do $$
declare t text;
begin
  foreach t in array array['foods', 'exercises'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for select to authenticated using (owner_id is null or owner_id = (select auth.uid()))', t || '_sel', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (owner_id = (select auth.uid()))', t || '_ins', t);
    execute format('create policy %I on public.%I for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()))', t || '_upd', t);
    execute format('create policy %I on public.%I for delete to authenticated using (owner_id = (select auth.uid()))', t || '_del', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()', t || '_updated_at', t);
  end loop;
end $$;

-- Read-only global catalog of activity types.
alter table public.activity_types enable row level security;
create policy activity_types_sel on public.activity_types for select to authenticated using (true);
grant select on public.activity_types to authenticated;

-- Strava tokens: locked down completely.
alter table public.strava_connections enable row level security;
revoke all on public.strava_connections from anon, authenticated;
create trigger strava_connections_updated_at before update on public.strava_connections
  for each row execute function public.set_updated_at();

create or replace function public.get_strava_status()
returns table (connected boolean, athlete_id bigint, last_sync_at timestamptz)
language sql
security definer
set search_path = ''
stable
as $$
  select true, c.athlete_id, c.last_sync_at
  from public.strava_connections c
  where c.user_id = (select auth.uid());
$$;
revoke all on function public.get_strava_status() from public, anon;
grant execute on function public.get_strava_status() to authenticated;

