-- ---------------------------------------------------------------- new-user bootstrap
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'));
  insert into public.user_preferences (user_id) values (new.id);
  insert into public.physical_profiles (user_id) values (new.id);
  insert into public.nutrition_settings (user_id) values (new.id);
  insert into public.meal_types (user_id, default_key, sort_order) values
    (new.id, 'breakfast', 1), (new.id, 'mid_morning', 2), (new.id, 'lunch', 3),
    (new.id, 'snack', 4), (new.id, 'dinner', 5), (new.id, 'other_snacks', 6);
  return new;
end;
$$;
